'use strict';
const $=id=>document.getElementById(id);
const colors=['#b5cfb1','#ebc864','#eda584','#d2b5d4','#9ac9cc','#e79687','#c8ca84','#b5bddf','#e5b6a0','#94b990','#efb96b'];
const names=['小眼神','小鼻子','微笑','小表情','好奇臉','偷笑臉','開心臉','得意臉','大笑臉','超級你','完整的你'];
const board=$('board'),ctx=board.getContext('2d'),nextCtx=$('next').getContext('2d');
let images=[],sources=Array(11).fill(null),score=0,best=0,soundOn=false,audioCtx=null;
let current=0,nextLevel=0,aimX=220,lastDrop=-10,paused=false,gameOver=false,overflowTime=0,lastFrame=0,accumulator=0,particles=[],danger=false;
let sourceImage=null,cropIndex=-1,sourceUrl=null,cropState={cx:0,cy:0,zoom:1},cropDrag=null,restorePause=false,loadTicket=0,toastTimer,confirmAction=null,confirmAccepted=false;
const physics=new MelonPhysics(onMerge);
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function safeRead(key,fallback){try{return localStorage.getItem(key)??fallback;}catch{return fallback;}}
best=Number(safeRead('photo-melon-best','0'))||0;$('best').textContent=best;
function writeBest(){try{localStorage.setItem('photo-melon-best',String(best));}catch{}}
function randomLevel(){const v=Math.random();return v<.4?0:v<.7?1:v<.9?2:3;}
function defaultImage(i){const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d');g.fillStyle=colors[i];g.fillRect(0,0,256,256);g.lineCap='round';g.strokeStyle='#314135';g.fillStyle='#314135';g.lineWidth=7;
 const ey=i>5?104:108,ex=38+(i%3)*3;
 if(i===0){g.beginPath();g.ellipse(128,128,69,38,0,0,Math.PI*2);g.fillStyle='#fffdf3';g.fill();g.fillStyle='#314135';g.beginPath();g.arc(133,128,23,0,Math.PI*2);g.fill();g.fillStyle='#fff';g.beginPath();g.arc(141,118,7,0,Math.PI*2);g.fill();}
 else if(i===1){g.beginPath();g.moveTo(128,71);g.lineTo(109,154);g.quadraticCurveTo(128,176,153,152);g.stroke();g.fillStyle='#fffdf320';g.beginPath();g.ellipse(127,129,53,71,0,0,Math.PI*2);g.fill();}
 else if(i===2){g.beginPath();g.moveTo(62,113);g.quadraticCurveTo(128,201,194,113);g.stroke();g.fillStyle='#fffdf3';g.beginPath();g.moveTo(70,120);g.quadraticCurveTo(128,183,186,120);g.closePath();g.fill();}
 else {for(const x of [128-ex,128+ex]){g.beginPath();if(i===8||i===10){g.arc(x,ey+6,13,Math.PI,Math.PI*2);g.stroke();}else if(i===5&&x>128){g.moveTo(x-12,ey);g.lineTo(x+12,ey);g.stroke();}else{g.ellipse(x,ey,7,12,0,0,Math.PI*2);g.fill();}}g.fillStyle='#e8786766';for(const x of [69,187]){g.beginPath();g.ellipse(x,140,16,10,0,0,Math.PI*2);g.fill();}g.strokeStyle='#314135';g.fillStyle='#314135';g.beginPath();if(i>=8){g.ellipse(128,163,27,25,0,0,Math.PI);g.closePath();g.fill();g.fillStyle='#ef8c82';g.beginPath();g.ellipse(128,178,15,7,0,0,Math.PI*2);g.fill();}else {g.arc(128,141,23,0.2,Math.PI-.2);g.stroke();}if(i===10){g.fillStyle='#fff4bd';g.beginPath();g.moveTo(93,61);g.lineTo(82,30);g.lineTo(113,43);g.lineTo(128,18);g.lineTo(143,43);g.lineTo(174,30);g.lineTo(163,61);g.closePath();g.fill();}}
 return c;}
function initializeDefaults(){images=names.map((_,i)=>defaultImage(i));sources=Array(11).fill(null);}
function drawPiece(g,im,x,y,r,angle=0,ring='#fffef9'){g.save();g.translate(x,y);g.rotate(angle);g.shadowColor='#29372e17';g.shadowBlur=5;g.shadowOffsetY=2;g.beginPath();g.arc(0,0,r,0,Math.PI*2);g.fillStyle=ring;g.fill();g.shadowBlur=0;g.shadowOffsetY=0;g.beginPath();g.arc(0,0,Math.max(1,r-2),0,Math.PI*2);g.clip();g.drawImage(im,-r,-r,r*2,r*2);g.restore();g.save();g.strokeStyle=ring;g.lineWidth=2;g.beginPath();g.arc(x,y,r-1,0,Math.PI*2);g.stroke();g.restore();}
function renderLevels(){const el=$('levels');el.replaceChildren();images.forEach((im,i)=>{const b=document.createElement('button');b.className='level';b.title=`第 ${i+1} 階：更換或裁切圖片`;b.setAttribute('aria-label',b.title);const num=document.createElement('span');num.className='level-num';num.textContent=String(i+1).padStart(2,'0');const c=document.createElement('canvas');c.width=c.height=96;drawPiece(c.getContext('2d'),im,48,48,45,0,colors[i]);const label=document.createElement('small');label.textContent=sources[i]?`照片 ${i+1}`:names[i];b.append(num,c,label);b.onclick=()=>editLevel(i);el.append(b);});drawNext();}
function drawNext(){nextCtx.clearRect(0,0,64,64);drawPiece(nextCtx,images[nextLevel],32,32,28,0,colors[nextLevel]);}
function beep(level){if(!soundOn)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(220*Math.pow(1.16,level),audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(440*Math.pow(1.1,level),audioCtx.currentTime+.13);g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.2);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.21);}catch{}}
function onMerge(b){score+=(b.level+1)*(b.level+1);$('score').textContent=score;if(score>best){best=score;$('best').textContent=best;writeBest();}for(let i=0;i<14;i++){const a=Math.random()*Math.PI*2,s=40+Math.random()*100;particles.push({x:b.x,y:b.y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,t:.65,color:colors[b.level]});}beep(b.level);$('live').textContent=`合成第 ${b.level+1} 階，目前 ${score} 分`;if(b.level===10)toast('合成完整的你！繼續挑戰最高分 ✳');}
function restart(){physics.reset();score=0;particles=[];overflowTime=0;gameOver=false;danger=false;paused=false;accumulator=0;lastDrop=-10;current=randomLevel();nextLevel=randomLevel();aimX=220;$('score').textContent='0';$('overlay').hidden=true;updatePauseButton();drawNext();}
function drop(){if(paused||gameOver||physics.time-lastDrop<.42||physics.balls.length>=180)return;physics.add(current,Math.max(MelonRadii[current]+3,Math.min(440-MelonRadii[current]-3,aimX)),43);lastDrop=physics.time;current=nextLevel;nextLevel=randomLevel();drawNext();}
function showOverlay(title,desc,action,icon='✳'){$('overlay-title').textContent=title;$('overlay-desc').textContent=desc;$('overlay-action').textContent=action;$('overlay-icon').textContent=icon;$('overlay').hidden=false;}
function updatePauseButton(){$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'繼續遊戲':'暫停遊戲');}
function togglePause(){if(gameOver)return;paused=!paused;updatePauseButton();if(paused)showOverlay('休息一下','你的下一顆正在等你。','繼續合成 →');else $('overlay').hidden=true;}
function draw(){ctx.clearRect(0,0,440,610);ctx.fillStyle='#fffdf3';ctx.fillRect(0,0,440,610);ctx.fillStyle='#e9e6d580';for(let x=20;x<440;x+=28)for(let y=15;y<610;y+=28){ctx.beginPath();ctx.arc(x,y,1,0,Math.PI*2);ctx.fill();}ctx.save();ctx.setLineDash([7,6]);ctx.strokeStyle=danger?'#ed7965':'#d8cfc0';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(0,93);ctx.lineTo(440,93);ctx.stroke();ctx.restore();ctx.fillStyle=danger?'#da654e':'#b1a894';ctx.font='10px system-ui';ctx.textAlign='left';ctx.fillText(danger?'快滿了！趕快合成':'不要堆過這條線',13,86);
 if(!gameOver){const r=MelonRadii[current],x=Math.max(r+3,Math.min(440-r-3,aimX));ctx.save();ctx.setLineDash([3,7]);ctx.strokeStyle='#a7af9670';ctx.beginPath();ctx.moveTo(x,43+r);let target=605;for(const b of physics.balls){const dx=Math.abs(b.x-x);if(dx<b.r+r)target=Math.min(target,b.y-Math.sqrt((b.r+r)**2-dx**2));}ctx.lineTo(x,Math.max(94,target));ctx.stroke();ctx.restore();ctx.globalAlpha=physics.time-lastDrop<.42?.45:1;drawPiece(ctx,images[current],x,43,r,0,colors[current]);ctx.globalAlpha=1;}
 for(const b of physics.balls)drawPiece(ctx,images[b.level],b.x,b.y,b.r,b.angle,colors[b.level]);for(const p of particles){ctx.globalAlpha=Math.max(0,p.t/.65);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;ctx.fillStyle='#dad4bd';ctx.fillRect(0,606,440,4);}
function frame(time){if(!lastFrame)lastFrame=time;const elapsed=Math.min((time-lastFrame)/1000,.05);lastFrame=time;if(!paused&&!gameOver){accumulator+=elapsed;while(accumulator>=1/120){physics.step(1/120);accumulator-=1/120;danger=physics.overflow();overflowTime=danger?overflowTime+1/120:Math.max(0,overflowTime-1/60);if(overflowTime>1.8){gameOver=true;showOverlay('差一點就合成了！',`這次得到 ${score} 分。換個角度，再挑戰一次。`,'再玩一次 →','◕');$('live').textContent=`遊戲結束，${score} 分`;break;}}for(const p of particles){p.t-=elapsed;p.x+=p.vx*elapsed;p.y+=p.vy*elapsed;p.vy+=170*elapsed;}particles=particles.filter(p=>p.t>0);}draw();requestAnimationFrame(frame);}
let boardPointer=null;
function aim(e){const r=board.getBoundingClientRect();aimX=Math.max(0,Math.min(440,(e.clientX-r.left)*440/r.width));}
board.addEventListener('pointerdown',e=>{if(e.button!==0||paused||gameOver)return;boardPointer=e.pointerId;board.setPointerCapture(e.pointerId);aim(e);});
board.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'||boardPointer===e.pointerId)aim(e);});
board.addEventListener('pointerup',e=>{if(boardPointer!==e.pointerId)return;aim(e);boardPointer=null;drop();});
board.addEventListener('pointercancel',()=>boardPointer=null);
board.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')aimX-=15;if(e.key==='ArrowRight')aimX+=15;if(e.key===' ')drop();if(e.key.toLowerCase()==='p')togglePause();});
$('pause').onclick=togglePause;$('overlay-action').onclick=()=>gameOver?restart():togglePause();
function confirmDialog(title,desc,button,action){restorePause=paused;paused=true;confirmAction=action;confirmAccepted=false;$('confirm-title').textContent=title;$('confirm-desc').textContent=desc;$('confirm-ok').textContent=button;$('confirm-modal').showModal();}
$('restart').onclick=()=>confirmDialog('重新開始？','目前的分數會歸零，你的照片素材會保留。','重新開始',restart);
$('confirm-cancel').onclick=()=>$('confirm-modal').close();$('confirm-modal').addEventListener('close',()=>{paused=restorePause;if(confirmAccepted)confirmAction();updatePauseButton();});
$('confirm-ok').onclick=()=>{confirmAccepted=true;$('confirm-modal').close();};
$('sound').onclick=()=>{soundOn=!soundOn;$('sound').textContent=soundOn?'♫':'♪';$('sound').setAttribute('aria-label',soundOn?'關閉音效':'開啟音效');$('sound').title=soundOn?'關閉音效':'開啟音效';toast(soundOn?'合成音效已開啟':'音效已關閉');if(soundOn)beep(1);};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&!paused&&!gameOver&&!$('crop-modal').open&&!$('confirm-modal').open)togglePause();});
async function decode(url){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('無法讀取照片'));im.src=url;});}
function requestPhoto(index=-1){cropIndex=index;$('photo-input').value='';$('photo-input').click();}
$('upload-main').onclick=()=>requestPhoto(-1);
$('photo-input').onchange=async e=>{const f=e.target.files[0];if(f)await loadFile(f,cropIndex);};
async function loadFile(file,index){if(file.size>15*1024*1024){toast('照片太大了，請選擇 15 MB 以下的圖片。');return;}if(!/^image\/(jpeg|png|webp)$/.test(file.type)){toast('請使用 JPG、PNG 或 WEBP 圖片。');return;}const ticket=++loadTicket;const url=URL.createObjectURL(file);try{const im=await decode(url);if(ticket!==loadTicket)return;const c=document.createElement('canvas'),ratio=Math.min(1,1200/Math.max(im.width,im.height));c.width=Math.round(im.width*ratio);c.height=Math.round(im.height*ratio);c.getContext('2d').drawImage(im,0,0,c.width,c.height);const data=c.toDataURL('image/jpeg',.86);const reduced=await decode(data);if(ticket!==loadTicket)return;sourceUrl=data;sourceImage=reduced;openCrop(index);}catch{toast('無法讀取這張照片，請換一張圖片。');}finally{URL.revokeObjectURL(url);}}
async function editLevel(index){cropIndex=index;const saved=sources[index];if(saved){const ticket=++loadTicket;try{const im=await decode(saved.url);if(ticket!==loadTicket)return;sourceUrl=saved.url;sourceImage=im;openCrop(index,saved.crop);}catch{requestPhoto(index);}}else requestPhoto(index);}
function openCrop(index,saved){cropIndex=index;if(!$('crop-modal').open){restorePause=paused;paused=true;$('crop-modal').showModal();}cropState=saved?{...saved}:{cx:sourceImage.width/2,cy:sourceImage.height/2,zoom:1};$('zoom').value=cropState.zoom;$('crop-title').textContent=index<0?'先圈選一張完整的臉':`圈選第 ${index+1} 階的素材`;$('crop-note').textContent=index<0?'先套用到全部 11 階；之後點選每一顆，分別圈出五官。':`相同第 ${index+1} 階碰撞後會合成下一階。`;paintCrop();}
function cropGeometry(){const side=Math.min(sourceImage.width,sourceImage.height)/cropState.zoom;cropState.cx=Math.max(side/2,Math.min(sourceImage.width-side/2,cropState.cx));cropState.cy=Math.max(side/2,Math.min(sourceImage.height-side/2,cropState.cy));return {side,sx:cropState.cx-side/2,sy:cropState.cy-side/2};}
function paintCrop(){if(!sourceImage)return;const g=$('crop').getContext('2d'),{side,sx,sy}=cropGeometry();g.clearRect(0,0,400,400);const scale=320/side;g.drawImage(sourceImage,40-sx*scale,40-sy*scale,sourceImage.width*scale,sourceImage.height*scale);g.fillStyle='#29372e75';g.beginPath();g.rect(0,0,400,400);g.arc(200,200,160,0,Math.PI*2,true);g.fill('evenodd');g.strokeStyle='#fffdf3';g.lineWidth=3;g.beginPath();g.arc(200,200,160,0,Math.PI*2);g.stroke();g.strokeStyle='#ffffff35';g.lineWidth=1;g.beginPath();g.moveTo(40,200);g.lineTo(360,200);g.moveTo(200,40);g.lineTo(200,360);g.stroke();$('zoom-value').textContent=Number(cropState.zoom).toFixed(1)+'×';}
$('zoom').oninput=e=>{cropState.zoom=Number(e.target.value);paintCrop();};
$('crop').addEventListener('pointerdown',e=>{cropDrag={id:e.pointerId,x:e.clientX,y:e.clientY,cx:cropState.cx,cy:cropState.cy};$('crop').setPointerCapture(e.pointerId);});
$('crop').addEventListener('pointermove',e=>{if(!cropDrag||e.pointerId!==cropDrag.id)return;const rect=$('crop').getBoundingClientRect(),side=Math.min(sourceImage.width,sourceImage.height)/cropState.zoom,scale=320/side*rect.width/400;cropState.cx=cropDrag.cx-(e.clientX-cropDrag.x)/scale;cropState.cy=cropDrag.cy-(e.clientY-cropDrag.y)/scale;paintCrop();});
$('crop').addEventListener('pointerup',()=>cropDrag=null);$('crop').addEventListener('pointercancel',()=>cropDrag=null);
function cropOutput(){const c=document.createElement('canvas');c.width=c.height=256;const {side,sx,sy}=cropGeometry();c.getContext('2d').drawImage(sourceImage,sx,sy,side,side,0,0,256,256);return c;}
$('crop-apply').onclick=()=>{const c=cropOutput(),saved={url:sourceUrl,crop:{...cropState},output:c.toDataURL('image/jpeg',.88)};if(cropIndex<0){images=Array.from({length:11},()=>c);sources=Array.from({length:11},()=>({...saved,crop:{...saved.crop}}));}else{images[cropIndex]=c;sources[cropIndex]=saved;}renderLevels();$('crop-modal').close();toast(cropIndex<0?'已套用到全部階段。點選各階，再圈選不同五官！':'這一階的照片已更新。');};
$('crop-replace').onclick=()=>requestPhoto(cropIndex);$('crop-close').onclick=()=>$('crop-modal').close();$('crop-modal').addEventListener('close',()=>{paused=restorePause;cropDrag=null;updatePauseButton();});
const zone=$('upload-zone');zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drag');});zone.addEventListener('dragleave',()=>zone.classList.remove('drag'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag');const f=e.dataTransfer.files[0];if(f)loadFile(f,-1);});
$('save-theme').onclick=()=>{try{const urls=[...new Set(sources.filter(Boolean).map(s=>s.url))];const levels=sources.map(s=>s?{source:urls.indexOf(s.url),crop:s.crop,output:s.output}:null);localStorage.setItem('photo-melon-theme',JSON.stringify({version:1,urls,levels}));toast('素材已儲存到這個瀏覽器。');}catch{toast('儲存空間不足或瀏覽器不允許儲存；目前仍可繼續遊玩。');}};
$('reset-theme').onclick=()=>confirmDialog('恢復預設素材？','所有階段會換回預設表情，並清除這個瀏覽器儲存的照片素材。','恢復預設',()=>{++loadTicket;initializeDefaults();sourceImage=null;sourceUrl=null;try{localStorage.removeItem('photo-melon-theme');}catch{}renderLevels();toast('已恢復預設表情。');});
$('capture').onclick=()=>{const c=document.createElement('canvas');c.width=440;c.height=680;const g=c.getContext('2d');g.fillStyle='#f7f4ec';g.fillRect(0,0,440,680);g.fillStyle='#29372e';g.font='bold 20px system-ui';g.fillText('PHOTO MELON · 合成我的臉',16,31);g.font='12px system-ui';g.fillText(`SCORE ${score}    BEST ${best}`,16,55);g.drawImage(board,0,70);c.toBlob(blob=>{if(!blob){toast('無法產生圖片，請稍後再試。');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='photo-melon-'+score+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},'image/png');};
async function restoreTheme(){const raw=safeRead('photo-melon-theme',null),ticket=loadTicket;if(!raw)return;try{const data=JSON.parse(raw);if(data.version!==1||data.levels.length!==11||!Array.isArray(data.urls))return;const loaded=await Promise.all(data.levels.map(async(s,i)=>s?await decode(s.output):defaultImage(i)));if(ticket!==loadTicket)return;images=loaded;sources=data.levels.map(s=>s?{url:data.urls[s.source],crop:s.crop,output:s.output}:null);renderLevels();}catch{toast('儲存素材無法讀取，已使用預設表情。');}}
initializeDefaults();renderLevels();restart();restoreTheme();requestAnimationFrame(frame);
